import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';

const PrivateFeedback = () => {
  const navigate = useNavigate();
  
  // 1. LIVE BACKEND URL (Isse manually change karne ki zaroorat nahi padegi)
  const BACKEND_URL = process.env.REACT_APP_API_URL || 'https://backend-munday-vercel-gsn8.vercel.app/munapi/user';

  const [formData, setFormData] = useState({
    name: '',
    email: '',
    contact: '',
    message: '',
    feedback: '',
    rating: 0
  });
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleSubmit = async () => {
    // Basic Validation
    if (!formData.name.trim()) { alert('Please enter your name'); return; }
    if (!formData.email.trim()) { alert('Please enter your email'); return; }
    if (!formData.contact.trim()) { alert('Please enter your contact number'); return; }
    if (!formData.message.trim() && !formData.feedback.trim()) {
      alert('Please enter your message or feedback');
      return;
    }

    setIsSubmitting(true);

    try {
      // 2. Fetch call using LIVE URL
      const response = await fetch(BACKEND_URL, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          name: formData.name,
          email: formData.email,
          contact: parseInt(formData.contact),
          message: formData.message || formData.feedback
        })
      });

      if (response.ok) {
        const result = await response.json();
        console.log('Success:', result);
        alert('Thank you! Your private feedback has been sent to our management.');
        navigate('/');
      } else {
        const error = await response.json();
        console.error('Error:', error);
        alert('Server error: ' + (error.message || 'Something went wrong.'));
      }
    } catch (error) {
      console.error('Network error:', error);
      alert('Connection Error: Please check if your internet is working.');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div style={{
      minHeight: '100vh',
      background: 'linear-gradient(135deg, #e74c3c 0%, #c0392b 100%)',
      display: 'flex',
      justifyContent: 'center',
      alignItems: 'center',
      padding: '20px',
      fontFamily: 'Arial, sans-serif'
    }}>
      <div style={{
        background: 'white',
        borderRadius: '20px',
        padding: '30px',
        maxWidth: '500px',
        width: '100%',
        boxShadow: '0 10px 30px rgba(0,0,0,0.2)'
      }}>
        
        <div style={{ textAlign: 'center', fontSize: '50px', marginBottom: '10px' }}>😔</div>

        <h2 style={{ textAlign: 'center', color: '#2c3e50', marginBottom: '5px' }}>
          We're sorry to hear that!
        </h2>
        
        <p style={{ textAlign: 'center', color: '#7f8c8d', marginBottom: '25px', fontSize: '14px' }}>
          Your feedback helps us improve. Please tell us what went wrong.
        </p>

        {/* Inputs */}
        <div style={{ marginBottom: '15px' }}>
          <label style={{ display: 'block', marginBottom: '5px', fontWeight: 'bold', fontSize: '14px' }}>Name *</label>
          <input type="text" name="name" value={formData.name} onChange={handleChange} placeholder="Enter your name" disabled={isSubmitting}
            style={inputStyle(isSubmitting)}
          />
        </div>

        <div style={{ marginBottom: '15px' }}>
          <label style={{ display: 'block', marginBottom: '5px', fontWeight: 'bold', fontSize: '14px' }}>Email *</label>
          <input type="email" name="email" value={formData.email} onChange={handleChange} placeholder="Enter your email" disabled={isSubmitting}
            style={inputStyle(isSubmitting)}
          />
        </div>

        <div style={{ marginBottom: '15px' }}>
          <label style={{ display: 'block', marginBottom: '5px', fontWeight: 'bold', fontSize: '14px' }}>Contact No *</label>
          <input type="tel" name="contact" value={formData.contact} onChange={handleChange} placeholder="Enter your contact number" disabled={isSubmitting}
            style={inputStyle(isSubmitting)}
          />
        </div>

        <div style={{ marginBottom: '20px' }}>
          <label style={{ display: 'block', marginBottom: '5px', fontWeight: 'bold', fontSize: '14px' }}>Message *</label>
          <textarea name="message" value={formData.message} onChange={handleChange} placeholder="Describe your experience..." disabled={isSubmitting}
            style={{ ...inputStyle(isSubmitting), height: '80px', resize: 'none' }}
          />
        </div>

        <button 
          onClick={handleSubmit}
          disabled={isSubmitting}
          style={{
            width: '100%',
            padding: '12px',
            background: isSubmitting ? '#bdc3c7' : '#e74c3c',
            color: 'white',
            border: 'none',
            borderRadius: '25px',
            fontSize: '16px',
            fontWeight: 'bold',
            cursor: isSubmitting ? 'not-allowed' : 'pointer',
            transition: '0.3s'
          }}
        >
          {isSubmitting ? 'Submitting...' : 'Send Private Feedback'}
        </button>

        <div style={{ 
          textAlign: 'center', fontSize: '11px', color: '#27ae60', background: '#d5f4e6',
          padding: '10px', borderRadius: '8px', marginTop: '20px'
        }}>
          🔒 Your feedback is private and will only be seen by our management team.
        </div>
      </div>
    </div>
  );
};

// Helper style function
const inputStyle = (disabled) => ({
  width: '100%',
  padding: '10px',
  border: '2px solid #eee',
  borderRadius: '8px',
  fontSize: '14px',
  boxSizing: 'border-box',
  outline: 'none',
  opacity: disabled ? 0.6 : 1
});

export default PrivateFeedback;
